import ast, pathlib, sys
for path in sorted(pathlib.Path('.').glob('*.py')):
    tree = ast.parse(path.read_text())
    src = path.read_text()
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names: imported.add((a.asname or a.name).split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            for a in node.names: imported.add(a.asname or a.name)
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    names |= {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    for n in ast.walk(tree):
        if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name):
            names.add(n.value.id)
    unused = sorted(i for i in imported if i not in names and i not in src.split('__all__')[0].count('x')*[])
    unused = [u for u in unused if src.count(u) <= 1]
    if unused:
        print(path, 'possibly unused imports:', unused)
